from pathlib import Path
import hashlib,json,sqlite3,stat,sys
out=Path(__file__).resolve().parent;f=json.loads((out/'fixture.json').read_text());root=Path(f['workspace_root']);current={str(p.relative_to(root)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in root.rglob('*') if p.is_file()};label=sys.argv[1]
expected=json.loads((out/'malformed-files.json').read_text()) if label=='refusal' else json.loads((out.parent/'g02-review-transition-2026-11-08/final-files.json').read_text());assert current==expected
c=sqlite3.connect('file:'+f['state']+'/state.db?mode=ro',uri=True);records={'operations':dict(c.execute('select id,payload from write_operations')),'batches':dict(c.execute("select key,value from state where key like 'batch:%'"))};assert records==json.loads((out.parent/'g02-review-transition-2026-11-08/final-records.json').read_text());assert set(c.execute('select worktree_id,revoked from write_trust'))=={(f['entries'][f[k]],0) for k in ['parent','middle','leaf']};assert c.execute('pragma integrity_check').fetchone()[0]=='ok';proof={'stage':label,'exact_repository_files_modes':True,'zero_new_batches_or_operations':True,'all_previous_operation_batch_payloads_exact':True,'unchanged_three_trusts_control_untrusted':True,'integrity':'ok'};(out/('verify-'+label+'.json')).write_text(json.dumps(proof,indent=2)+'\n');trace=(Path(f['state'])/'native-acceptance-events.jsonl').read_text().splitlines()[f['trace_initial_lines']:];(out/'trace.jsonl').write_text('\n'.join(trace)+'\n');print(proof)
